import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"记录一次iPhone维修经历","description":"用了将近一年的iPhone 7 Plus的后置摄像头摔坏了，外观无损伤，但无法拍照。保修期内，Apple直营店在更换摄像头无果后，返厂维修，顺便免费更换了主板、电池、屏幕（好像赠送了Apple Care），好吧，除了手机后壳几乎都换掉了，拿回几乎全新的手机。感谢苹果~","frontmatter":{"title":"记录一次iPhone维修经历","sidebarTitle":"iPhone维修记","description":"用了将近一年的iPhone 7 Plus的后置摄像头摔坏了，外观无损伤，但无法拍照。保修期内，Apple直营店在更换摄像头无果后，返厂维修，顺便免费更换了主板、电池、屏幕（好像赠送了Apple Care），好吧，除了手机后壳几乎都换掉了，拿回几乎全新的手机。感谢苹果~","date":"2018-05-05T00:00:00.000Z","category":"随笔","tags":["日记"]},"headers":[],"relativePath":"articles/notes/diary/iphone7plus.md","filePath":"articles/notes/diary/iphone7plus.md","articleMeta":{"updated":"2018-05-05","words":1638,"minutes":4}}`),a={name:`articles/notes/diary/iphone7plus.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t("",22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};